def resolve(path, cwd, links):
    def split(p):
        return [c for c in p.split('/') if c not in ('', '.')]

    if path.startswith('/'):
        components = split(path)
    else:
        components = split(cwd) + split(path)

    result = []
    link_count = 0

    while components:
        comp = components.pop(0)
        if comp == '..':
            if result:
                result.pop()
            continue
        result.append(comp)
        current_path = '/' + '/'.join(result)
        if current_path in links:
            link_count += 1
            if link_count > 8:
                return None
            target = links[current_path]
            if target.startswith('/'):
                new_components = split(target)
                result = []
            else:
                parent = result[:-1]
                new_components = split(target)
                result = parent
            components = new_components + components

    if not result:
        return '/'
    return '/' + '/'.join(result)

